begin;
select no_plan();
create temp table ids as select gen_random_uuid() owner, gen_random_uuid() artist, gen_random_uuid() event, gen_random_uuid() product, gen_random_uuid() other;
insert into auth.users(id,email) select owner,'allocation-integrity@example.local' from ids;
insert into public.artists(id,slug,display_name) select artist,'allocation-integrity','Allocation integrity' from ids;
insert into public.artist_members(artist_id,member_email,role,status) select artist,'allocation-integrity@example.local','owner','active' from ids;
select set_config('request.jwt.claims',jsonb_build_object('sub',owner,'email','allocation-integrity@example.local','role','authenticated')::text,true) from ids;
insert into public.events(id,artist_id,event_name,start_date,end_date,status) select event,artist,'Event',now()-interval '1 hour',now()+interval '1 day','Confirmed' from ids;
insert into public.products(id,artist_id,name,price,stock_total,stock_reserved,stock_sold,is_unlimited) select product,artist,'Product',100,50,0,0,false from ids;
insert into public.products(id,artist_id,name,price,stock_total,stock_reserved,stock_sold,is_unlimited) select other,artist,'Other',100,50,0,0,false from ids;
select throws_ok($$ select public.save_event_catalog((select event from ids),jsonb_build_array(jsonb_build_object('product_id',(select other from ids),'stock_total',10,'is_unlimited',false),jsonb_build_object('product_id',(select product from ids),'stock_total',100,'is_unlimited',false))) $$,'event_stock_exceeds_catalog_stock','over-allocation rejected atomically');
select is((select count(*)::integer from public.event_products where event_id=(select event from ids)),0,'failed multi-item request persists no rows');
select lives_ok($$ select public.save_event_catalog((select event from ids),jsonb_build_array(jsonb_build_object('product_id',(select product from ids),'stock_total',50,'is_unlimited',false))) $$,'allocate all 50');
select is((select stock_total from public.event_products where event_id=(select event from ids)),50,'saved allocation is 50');
select throws_ok($$ select public.save_event_catalog((select event from ids),jsonb_build_array(jsonb_build_object('product_id',(select product from ids),'stock_total',100,'is_unlimited',false))) $$,'event_stock_exceeds_catalog_stock','increase beyond total rejected');
select is((select stock_total from public.event_products where event_id=(select event from ids)),50,'failed increase leaves persisted value unchanged');
update public.products set stock_total=80 where id=(select product from ids);
select lives_ok($$ select public.remove_event_stock((select id from public.event_products where event_id=(select event from ids)),20) $$,'return 20 leaves existing allocation of 30');
select is((select available from public.list_product_stock_summaries((select artist from ids)) where product_id=(select product from ids)),50,'50 units remain available after allocating 30 of 80');
select throws_ok($$ select public.add_event_stock((select id from public.event_products where event_id=(select event from ids)),70) $$,'insufficient_catalog_available_stock','cannot increase allocation from 30 to 100');
select is((select stock_total from public.event_products where event_id=(select event from ids)),30,'failed increase preserves 30');
select lives_ok($$ select public.add_event_stock((select id from public.event_products where event_id=(select event from ids)),50) $$,'can increase allocation from 30 to 80');
select is((select stock_total from public.event_products where event_id=(select event from ids)),80,'successful increase persists 80');
update public.event_products set stock_reserved=3, stock_sold=2 where event_id=(select event from ids);
select throws_ok($$ select public.remove_event_stock((select id from public.event_products where event_id=(select event from ids)),76) $$,'event_stock_below_reserved_or_sold','cannot return sold or reserved stock');
select is((select stock_total from public.event_products where event_id=(select event from ids)),80,'failed return preserves 80');
select * from finish();
rollback;
